import{_ as t,o,c as r,a8 as i,j as l,a as e}from"./chunks/framework.BcVvFr-R.js";const m=JSON.parse('{"title":"模拟技术面试（AI 自动搜索面经版）","description":"","frontmatter":{"tags":["interview","career","mock","auto-search"],"version":"2.0.0","last_updated":"2026-09-04T00:00:00.000Z"},"headers":[],"relativePath":"09-面试/mock-interview.md","filePath":"09-面试/mock-interview.md"}'),n={name:"09-面试/mock-interview.md"};function s(d,a,h,u,c,p){return o(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1788664306000"},[...a[0]||(a[0]=[i('<h1 id="模拟技术面试-ai-自动搜索面经版" tabindex="-1">模拟技术面试（AI 自动搜索面经版） <a class="header-anchor" href="#模拟技术面试-ai-自动搜索面经版" aria-label="Permalink to &quot;模拟技术面试（AI 自动搜索面经版）&quot;">​</a></h1><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>准备面试时，希望 AI 根据你的简历和目标公司 JD，<strong>自动去牛客、小红书等平台搜索真实面经</strong>，然后针对性地出题模拟面试。</p><h2 id="输入说明" tabindex="-1">输入说明 <a class="header-anchor" href="#输入说明" aria-label="Permalink to &quot;输入说明&quot;">​</a></h2><p>请提供以下材料：</p><p><strong>1. 你的最新简历</strong>（重点突出项目经验和技术栈）</p><p><strong>2. 目标公司 + 岗位信息</strong>（如“字节跳动 后端开发工程师（校招）”或直接贴 JD 链接/文字/图片）</p><h2 id="ai-执行流程" tabindex="-1">AI 执行流程 <a class="header-anchor" href="#ai-执行流程" aria-label="Permalink to &quot;AI 执行流程&quot;">​</a></h2><h3 id="第一步-解析简历与-jd" tabindex="-1">第一步：解析简历与 JD <a class="header-anchor" href="#第一步-解析简历与-jd" aria-label="Permalink to &quot;第一步：解析简历与 JD&quot;">​</a></h3><ul><li>从简历中提取：技术栈、项目经验、工作年限、核心亮点</li><li>从 JD 中提取：岗位要求、技术关键词、面试轮次说明</li></ul><h3 id="第二步-自动搜索面经" tabindex="-1">第二步：自动搜索面经 <a class="header-anchor" href="#第二步-自动搜索面经" aria-label="Permalink to &quot;第二步：自动搜索面经&quot;">​</a></h3><p>使用联网搜索能力，按以下关键词组合进行搜索：</p><ul><li><code>{公司名} {岗位名} 面经 2026</code></li><li><code>{公司名} {技术栈} 面试经验</code></li><li><code>{公司名} {岗位名} 技术面 真题</code></li></ul><p><strong>搜索来源优先级：</strong></p><ol><li>牛客网（面经最全、时效性强）</li><li>小红书（近期面经细节丰富）</li><li>博客/技术社区（深度解析）</li></ol><p><strong>搜索策略：</strong></p><ul><li>优先获取近 30 天内的面经，保障时效性</li><li>至少抓取 3-5 篇不同来源的面经进行交叉对比</li><li>标注出现频次 ≥ 3 次的高频考点</li></ul><h3 id="第三步-生成面经分析报告" tabindex="-1">第三步：生成面经分析报告 <a class="header-anchor" href="#第三步-生成面经分析报告" aria-label="Permalink to &quot;第三步：生成面经分析报告&quot;">​</a></h3>',18),l("p",{岗位名:""},[e("基于搜索结果，输出一份结构化报告： 📊 面经分析报告 "),l("strong",null,"目标公司："),e(" {公司名} "),l("strong",null,"岗位：")],-1),l("p",null,[l("strong",null,"高频考点 Top5：")],-1),l("ol",null,[l("li",null,"{考点1}（出现次数：X/5）"),l("li",null,"{考点2}（出现次数：X/5）")],-1),l("p",null,[l("strong",null,"面试风格判断：")],-1),l("ul",null,[l("li",null,"技术深挖程度：深/中/浅"),l("li",null,"是否有系统设计题：是/否"),l("li",null,"面试官风格：强势追问/温和引导")],-1),l("p",{从面经中提取的追问路径示例:""},[l("strong",null,"典型追问链：")],-1),i('<h3 id="第四步-模拟面试" tabindex="-1">第四步：模拟面试 <a class="header-anchor" href="#第四步-模拟面试" aria-label="Permalink to &quot;第四步：模拟面试&quot;">​</a></h3><p>基于面经分析报告 + 你的简历 + JD，进行针对性模拟面试：</p><ol><li>技术问答（8-10题）：优先覆盖高频考点，结合简历项目深挖</li><li>系统设计题（如面经显示有该环节）</li><li>追问模拟：模拟面试官的层层追问（参考面经中的追问逻辑）</li><li>反问环节建议</li></ol><h3 id="第五步-面试反馈" tabindex="-1">第五步：面试反馈 <a class="header-anchor" href="#第五步-面试反馈" aria-label="Permalink to &quot;第五步：面试反馈&quot;">​</a></h3><ul><li>结构性评价</li><li>薄弱环节 Top3</li><li>针对性练习建议</li></ul><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><p><strong>用户输入：</strong></p><ul><li>简历：3年 Java 经验，Spring Cloud 项目，负责订单模块</li><li>目标公司：字节跳动 后端开发工程师</li></ul><p><strong>AI 执行：</strong></p><ol><li>提取关键词 → 搜索“字节跳动 后端 面经 2026”</li><li>抓取 5 篇面经，识别高频考点</li><li>生成面经分析报告</li><li>结合简历中的订单模块，针对性出题</li><li>逐题点评、追问、打分</li></ol><h2 id="迭代记录" tabindex="-1">迭代记录 <a class="header-anchor" href="#迭代记录" aria-label="Permalink to &quot;迭代记录&quot;">​</a></h2><ul><li>1.0.0 (2026-09-03): 初始版本（通用模拟面试）</li><li>2.0.0 (2026-09-04): AI 自动联网搜索面经，无需用户手动粘贴</li></ul>',12)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
